<script lang="ts">
  import { L } from '../lib/sitzung.svelte';
  import SeitenKopf from '../bausteine/SeitenKopf.svelte';
  import Marke from '../bausteine/Marke.svelte';
  import PlakatLink from '../bausteine/PlakatLink.svelte';
  import { MELDEN_SERVER } from '../lib/melden';
  import { OFFLINE, OFFLINE_PAKET, offlineStandText, offlinePaketStand } from '../lib/offline';
  import { ganzZahl } from '../i18n/profil';
  import { zaehle, zaehlenAbgeschaltet, zaehlenAbschalten, zaehlenAnschalten, browserNichtVerfolgen } from '../lib/zaehlen';
  import { CSP_TEXT, externeQuellen } from '../lib/csp';   // Wortlaut aus DEPLOY.md beim Bau (vite.config.ts, define __CSP__)
  import RPAKETE from '../lib/rpakete.json';   // erzeugt aus scripts/webr-PACKAGES (scripts/rechtliches-pakete.mjs); der Test lib/rpakete.test.ts hält sie aktuell
  /** Impressum und Datenschutz in einer Datei, damit beide Sprachen und beide Texte nebeneinander bleiben.
   *  Datenschutz gemessen am 07.10.2026: keine Cookies, keine fremden Adressen (CSP connect-src 'self'). Seit 31.10.2026 (Fachblatt SAISON-EUROSTAT): connect-src nennt zusätzlich https://ec.europa.eu - nur auf Klick bei „Von Eurostat laden“ geht eine Anfrage an die Europäische Kommission, ihr Server sieht IP-Adresse und Abfrage; in der Offline-Fassung gibt es das nicht. Alle Sätze dazu stehen nur, wenn OFFLINE nicht gilt,
   *  im Caddyfile kein `log` - der Server schreibt keine Zugriffsprotokolle. Wer das ändert, ändert diesen Text.
   *  Seit 25.10.2026 (Johannes): Besucherzählung mit Geräte-Merker und Schalter (lib/zaehlen.ts, server/pb_hooks/zaehlung.pb.js) - nur mit Server,
   *  darum stehen alle Sätze dazu unter MELDEN_SERVER; die Offline-Fassung zählt nicht und behält die alten Sätze.
   *  Je Absatz ein Paar (Bauplan Sprachen: Rechtliches in jeder Sprache, Johannes 09.10.); übersetzt wird nur der Inhalt, die Hülle bleibt hier.
   *  Der Inhalt ist eigener, fester Text mit wenigen Tags (a, strong, br, li, code) - darum {@html}.
   *  Seit 31.10.2026 (Fachblatt BEHOERDEN, Abschnitt 7): dritte Art 'behoerden' (#behoerden) - Angaben für Behörden und Rechenzentren, je Bauart mit und ohne Server;
   *  nur Belegtes, offene Punkte stehen als „offen“ da. Die Zahlen (R-Pakete) und die Content-Security-Policy kommen aus den Quellen, nicht von Hand.
 *  Seit 06.11.2026 (Barrierefreiheit, Welle 7C): vierte Art 'barrierefreiheit' (#barrierefreiheit) - Erklärung zur Barrierefreiheit nach dem österreichischen Muster.
 *  Nur belegte Aussagen aus docs/barrierefreiheit/ABSCHLUSS.md und WCAG-2.2-AA.md; die Zahlen darin prüft lib/erklaerung-waechter.test.ts gegen ABSCHLUSS.md. */
  let { art }: { art: 'impressum' | 'datenschutz' | 'behoerden' | 'barrierefreiheit' } = $props();
  /** Offline-Paket (Johannes 24.10.: auch im Impressum, nicht nur in den Einstellungen) - Stand und Größe aus offline/stand.json. */
  let paket = $state<{ stand: string; bytes: number } | null>(null);
  void offlinePaketStand().then(j => { paket = j; });
  /** Fremde Adressen in der Content-Security-Policy (Blatt „Für Behörden“): leer = keine. */
  const externe = externeQuellen(CSP_TEXT);
  /** Schalter der Besucherzählung (gilt für diesen Browser). */
  let zaehlAus = $state(zaehlenAbgeschaltet());
  const nichtVerfolgen = browserNichtVerfolgen();
  function zaehlSchalten() { if (zaehlAus) zaehlenAnschalten(); else zaehlenAbschalten(); zaehlAus = zaehlenAbgeschaltet(); }
</script>

{#snippet fremdeDienste()}
  {#if OFFLINE}<li>{L("Keine fremden Dienste: Schriften und Programmteile kommen vom selben Server.", "No third-party services: fonts and program files come from the same server.")}</li>
  {:else}<li>{L("Schriften und Programmteile kommen vom selben Server. Nur beim Klick auf „Von Eurostat laden“ oder „Grenzen von Eurostat laden“ geht eine Anfrage an die Europäische Kommission (siehe unten).", "Fonts and program files come from the same server. Only when \"Load from Eurostat\" or \"Load boundaries from Eurostat\" is clicked does a request go to the European Commission (see below).")}</li>{/if}
{/snippet}

<div class="tisch ohne-rand"><section class="blatt rund recht" aria-labelledby="re-t">
  {#if art === 'impressum'}
    <SeitenKopf titelId="re-t" titel={L('Impressum', 'Legal notice')} zurueck />
      <p class="recht-marke"><Marke groesse={48} /></p>
      <p>{@html L("Erstellt von Johannes Weingartner mit Hilfe von Claude Code<br>Königstetten, Österreich<br><a href=\"https://statable.eu\">statable.eu</a><br><a href=\"mailto:service@statable.eu\">service@statable.eu</a>", "Made by Johannes Weingartner with the help of Claude Code<br>Königstetten, Austria<br><a href=\"https://statable.eu\">statable.eu</a><br><a href=\"mailto:service@statable.eu\">service@statable.eu</a>")}</p>
      <p>{@html L("Statable ist ein privates, nicht-kommerzielles Werkzeug für Statistik in Studium, Lehre und Forschung. Es gibt keine Werbung und keine Konten.", "Statable is a private, non-commercial tool for statistics in study, teaching and research. There are no ads and no accounts.")}</p>
      <h2>{L("Freie Software", "Free software")}</h2>
      <p>{@html L("<strong>Statable ist freie Software</strong> (Open Source) unter der GNU General Public License, Version 3 oder später. Jede und jeder darf das Programm nutzen, weitergeben und verändern. <a href=\"statable-quelltext.tar.gz\" download>Quelltext von Statable herunterladen</a> (mit Lizenztext und den kleinen Änderungen an PSPP).", "<strong>Statable is free software</strong> (open source) under the GNU General Public License, version 3 or later. Anyone may use, share and change it. <a href=\"statable-quelltext.tar.gz\" download>Download the Statable source code</a> (with the license text and the small changes to PSPP).")}</p>
      <p>{@html L("Statable rechnet mit <strong>GNU PSPP 2.1.3</strong>, einem freien Statistikprogramm des GNU-Projekts (© Free Software Foundation, GPL Version 3 oder später). Statable übersetzt PSPP in WebAssembly, damit es im Browser läuft.<br>Projektseite: <a href=\"https://www.gnu.org/software/pspp/\" rel=\"noopener\">gnu.org/software/pspp</a> · Quelltext: <a href=\"https://ftp.gnu.org/gnu/pspp/\" rel=\"noopener\">ftp.gnu.org/gnu/pspp</a>", "Statable calculates with <strong>GNU PSPP 2.1.3</strong>, a free statistics program from the GNU Project (© Free Software Foundation, GPL version 3 or later). Statable compiles PSPP to WebAssembly so it runs in the browser.<br>Project page: <a href=\"https://www.gnu.org/software/pspp/\" rel=\"noopener\">gnu.org/software/pspp</a> · Source: <a href=\"https://ftp.gnu.org/gnu/pspp/\" rel=\"noopener\">ftp.gnu.org/gnu/pspp</a>")}</p>
      <p>{@html L("Für Verfahren, die PSPP nicht kann (McDonalds Omega, konfirmatorische Faktorenanalyse, Mehrebenen-Modelle, Meta-Analyse, ordinale, multinomiale und Zähldaten-Regression, Cox-Regression, Umfragegewichte, Quantilregression, Ridge, Lasso und Elastic Net), lädt Statable auf Wunsch <strong>R 4.6.0</strong> (GPL Version 2 oder 3, © R Foundation for Statistical Computing) in der WebAssembly-Fassung <strong>webR 0.6.0</strong> (der webR-Code steht unter der MIT-Lizenz, die mitgelieferten Binärdateien von R unter GPL Version 3). Dazu kommen die R-Pakete aus der Liste weiter unten, jeweils mit Version und Lizenz (GPL, LGPL, Apache 2.0 oder vergleichbar frei). lmerTest wird ohne seine Zeichenfunktionen ausgeliefert (der Import von ggplot2 ist entfernt, der Rechencode ist unverändert). Bei glmnet und survey wird im Paketindex die Angabe der nur beim Übersetzen gebrauchten Pakete (LinkingTo) angepasst; am Paket selbst ist nichts verändert. Alles kommt von diesem Server; es wird erst geladen, wenn man ein solches Verfahren startet.<br>Quelltext genau dieser Versionen: R <a href=\"https://cran.r-project.org/src/base/R-4/R-4.6.0.tar.gz\" rel=\"noopener\">cran.r-project.org/src/base/R-4/R-4.6.0.tar.gz</a> · webR <a href=\"https://github.com/r-wasm/webr\" rel=\"noopener\">github.com/r-wasm/webr</a> (Version 0.6.0) · Pakete <a href=\"https://cran.r-project.org/src/contrib/Archive/\" rel=\"noopener\">cran.r-project.org/src/contrib</a>. Die vollständige Liste mit Bauanleitung steht im Quelltext-Paket von Statable (<code>scripts/webr-QUELLTEXT.txt</code>).", "For methods PSPP cannot do (McDonald's omega, confirmatory factor analysis, multilevel models, meta-analysis, ordinal, multinomial and count regression, Cox regression, survey weights, quantile regression, ridge, lasso and elastic net), Statable loads on request <strong>R 4.6.0</strong> (GPL version 2 or 3, © R Foundation for Statistical Computing) in its WebAssembly build <strong>webR 0.6.0</strong> (the webR code is under the MIT license, the bundled R binaries under GPL version 3). In addition there are the R packages in the list below, each with version and license (GPL, LGPL, Apache 2.0 or comparably free). lmerTest is shipped without its plotting functions (the import of ggplot2 is removed, the calculation code is unchanged). For glmnet and survey the entry of the packages needed only for compiling (LinkingTo) is adjusted in the package index; the package itself is unchanged. Everything comes from this server; it is loaded only when you start such a method.<br>Source code of exactly these versions: R <a href=\"https://cran.r-project.org/src/base/R-4/R-4.6.0.tar.gz\" rel=\"noopener\">cran.r-project.org/src/base/R-4/R-4.6.0.tar.gz</a> · webR <a href=\"https://github.com/r-wasm/webr\" rel=\"noopener\">github.com/r-wasm/webr</a> (version 0.6.0) · packages <a href=\"https://cran.r-project.org/src/contrib/Archive/\" rel=\"noopener\">cran.r-project.org/src/contrib</a>. The full list with build instructions is in the Statable source package (<code>scripts/webr-QUELLTEXT.txt</code>).")}</p>
      <h2>{L("R-Pakete", "R packages")}</h2>
      <p>{L("Diese R-Pakete liefert Statable zusammen mit R aus (Paket, Version, Lizenz). Die Liste wird beim Holen der Pakete aus dem Paketindex erzeugt und kann darum nicht hinter dem Stand zurückbleiben.", "Statable ships these R packages together with R (package, version, license). The list is generated from the package index when the packages are fetched, so it cannot fall behind.")}</p>
      <ul class="rpakete">{#each RPAKETE as p (p.paket)}<li><code>{p.paket}</code> {p.version} - {p.lizenz}</li>{/each}</ul>
      <p>{L("Klassifikationen: ÖNACE 2008, ÖNACE 2025 und ISCO-08 (nur die Struktur mit Ebene, Code und Titel, deutsch und englisch) stammen aus der Klassifikationsdatenbank von Statistik Austria. Lizenz: Creative Commons Namensnennung 4.0 International (CC BY 4.0). Datenquelle: Statistik Austria - data.statistik.gv.at. Sie werden erst geladen, wenn man einer Spalte eine Klassifikation zuordnet.", "Classifications: ÖNACE 2008, ÖNACE 2025 and ISCO-08 (the structure only, with level, code and title, German and English) come from the classification database of Statistik Austria. Licence: Creative Commons Attribution 4.0 International (CC BY 4.0). Data source: Statistik Austria - data.statistik.gv.at. They are loaded only when a classification is assigned to a column.")}</p>
      <p>{L("Karten: Statable bringt die Grenzen der Staaten der Welt und der obersten Gliederung vieler Länder mit. Sie stammen von Natural Earth (gemeinfrei) und von geoBoundaries (gbOpen); bei geoBoundaries gilt die Lizenz des jeweiligen Landes und steht im Bild der Karte (Creative Commons mit Namensnennung, CC0 oder gemeinfrei, bei vielen Ländern ODbL oder CC BY-SA; diese Dateien bleiben eigene Datenwerke unter ihrer Lizenz, getrennt vom Programm unter der GPL). Lädt man Grenzen von Eurostat (GISCO), gilt der Vermerk „© EuroGeographics bezüglich der Verwaltungsgrenzen“; die Grenzen dürfen nur nicht-kommerziell verwendet werden.", "Maps: Statable includes the boundaries of the countries of the world and of the top-level division of many countries. They come from Natural Earth (public domain) and from geoBoundaries (gbOpen); for geoBoundaries the licence of each country applies and is shown in the image of the map (Creative Commons with attribution, CC0 or public domain, for many countries ODbL or CC BY-SA; these files remain separate datasets under their own licence, apart from the program under the GPL). When boundaries are loaded from Eurostat (GISCO), the notice \"© EuroGeographics for the administrative boundaries\" applies; the boundaries may only be used non-commercially.")}</p>
      <p>{L("NUTS: Die Gliederung NUTS 2021 und NUTS 2024 (Codes und Namen der Gebietseinheiten, auch die Statistischen Regionen einiger Länder außerhalb der EU) stammt von Eurostat. Eurostat gestattet die Wiederverwendung seiner Statistiken und Metadaten für kommerzielle und nicht-kommerzielle Zwecke, wenn die Quelle genannt wird (Beschluss 2011/833/EU der Kommission). Datenquelle: Eurostat - NUTS (Systematik der Gebietseinheiten für die Statistik). Die Grenzen der Regionen gehören nicht dazu und werden nicht mitgeliefert. Die Namen werden erst geladen, wenn man einer Spalte NUTS zuordnet.", "NUTS: The NUTS 2021 and NUTS 2024 classification (codes and names of the territorial units, including the statistical regions of some countries outside the EU) comes from Eurostat. Eurostat authorises the re-use of its statistics and metadata for commercial and non-commercial purposes provided the source is acknowledged (Commission Decision 2011/833/EU). Data source: Eurostat - NUTS (nomenclature of territorial units for statistics). The boundaries of the regions are not part of it and are not shipped. The names are loaded only when NUTS is assigned to a column.")}</p>
      <p>{L("Bezirke und Gemeinden Österreichs: Die Grenzen stammen aus den Verwaltungsgrenzen (VGD) des Bundesamts für Eich- und Vermessungswesen (BEV), Stichtag 01.04.2026, Lizenz: Creative Commons Namensnennung 4.0 International (CC BY 4.0). Datenquelle: Bundesamt für Eich- und Vermessungswesen (BEV) - Verwaltungsgrenzen. Änderungen: Katastralgemeinden zu Gemeinden und Bezirken zusammengefasst, umgerechnet und stark vereinfacht. Sie werden erst geladen, wenn man sie auf der Seite „Karte“ wählt.", "Districts and municipalities of Austria: The boundaries come from the administrative boundaries (VGD) of the Federal Office of Metrology and Surveying (BEV), as of 1 April 2026, licence: Creative Commons Attribution 4.0 International (CC BY 4.0). Data source: Bundesamt für Eich- und Vermessungswesen (BEV) - Verwaltungsgrenzen. Changes: cadastral municipalities merged into municipalities and districts, converted and strongly simplified. They are loaded only when chosen on the page \"Map\".")}</p>
      <p>{@html L("Weitere freie Bausteine: Svelte (MIT), docx (MIT), ExcelJS (MIT), SheetJS (Apache 2.0). Schriften: Atkinson Hyperlegible Next (SIL Open Font License) sowie Atkinson Hyperlegible (Braille Institute of America; laut Schriftdatei kostenlos nutzbar, ohne Ableitungen oder Änderung).", "Other free components: Svelte (MIT), docx (MIT), ExcelJS (MIT), SheetJS (Apache 2.0). Fonts: Atkinson Hyperlegible Next (SIL Open Font License) and Atkinson Hyperlegible (Braille Institute of America; according to the font file free to use, without derivatives or alteration).")}</p>
      <p>{L("Text aus PDF-Dokumenten liest pdf.js (pdfjs-dist, Apache 2.0).", "Text from PDF documents is read by pdf.js (pdfjs-dist, Apache 2.0).")}</p>
      <h2>{L("Statable zitieren", "Citing Statable")}</h2>
      <p>{@html L("Weingartner, J. (2026). <i>Statable: statistics in the browser for study and research</i> [Computersoftware]. Zenodo. <a href=\"https://doi.org/10.5281/zenodo.23627103\" rel=\"noopener\">https://doi.org/10.5281/zenodo.23627103</a>", "Weingartner, J. (2026). <i>Statable: statistics in the browser for study and research</i> [Computer software]. Zenodo. <a href=\"https://doi.org/10.5281/zenodo.23627103\" rel=\"noopener\">https://doi.org/10.5281/zenodo.23627103</a>")}</p>
      <h2>{L("Marken", "Trademarks")}</h2>
      <p>{L("SPSS ist eine eingetragene Marke der IBM Corporation. Stata, SAS, Microsoft Excel, TI-84, GeoGebra, jamovi und JASP sind Marken ihrer jeweiligen Inhaber. Statable steht in keiner Verbindung zu diesen Unternehmen und Projekten und wird von ihnen weder unterstützt noch geprüft. Die Namen stehen nur, um Dateiformate, Befehle und Programmvergleiche zu beschreiben.", "SPSS is a registered trademark of IBM Corporation. Stata, SAS, Microsoft Excel, TI-84, GeoGebra, jamovi and JASP are trademarks of their respective owners. Statable is not affiliated with, endorsed by or reviewed by these companies and projects. The names are used only to describe file formats, commands and comparisons.")}</p>
      <h2>{L("Ohne Netz: Offline-Fassung", "Without internet: offline version")}</h2>
      {#if OFFLINE}
        <p>{L(`Diese Fassung ist die Offline-Fassung vom ${offlineStandText()}. Sie wird nicht aktualisiert; auf Dauer bitte statable.eu verwenden.`, `This is the offline version from ${offlineStandText()}. It is not updated; for regular use, please use statable.eu.`)}</p>
      {:else}
        <p>{L('Für Prüfungen und Orte ohne Netz gibt es Statable als Paket zum Herunterladen: entpacken, doppelklicken, es läuft am Rechner ohne Internet (Windows, Mac, Linux). Auf Dauer nicht empfohlen - die Offline-Fassung wird nicht aktualisiert.', 'For exams and places without internet, Statable is available as a package to download: unzip, double-click, and it runs on the computer without internet (Windows, Mac, Linux). Not recommended for regular use - the offline version is not updated.')}</p>
        {#if paket}<p><a class="k" href={OFFLINE_PAKET} download onclick={() => zaehle('offline', 'zip')}>{L(`Offline-Fassung herunterladen (ZIP, ${ganzZahl(Math.round(paket.bytes / 1e6))} MB)`, `Download the offline version (ZIP, ${ganzZahl(Math.round(paket.bytes / 1e6))} MB)`)}</a></p>{/if}
      {/if}
      <h2>{L("Plakat", "Poster")}</h2>
      <p>{L('Ein Plakat zum Ausdrucken - für ein schwarzes Brett, eine Lehrveranstaltung oder ein Büro.', 'A poster to print - for a notice board, a course or an office.')}</p>
      <PlakatLink alle />
      <h2>{L("Haftung", "Liability")}</h2>
      <p>{@html L("Die Ergebnisse rechnen GNU PSPP, R und eigener Code von Statable. Sie sind an festen Beispielen gegen R und weitere Quellen geprüft (Prüfbericht auf der Seite „Für Behörden und Rechenzentren“). Das ist keine Gewähr, dass jede Rechnung auf allen Daten richtig ist. Für Inhalte verlinkter Seiten sind deren Betreiber verantwortlich.", "The results are calculated by GNU PSPP, R and Statable's own code. They are checked against R and other sources on fixed examples (test report on the page \"For public bodies and data centres\"). This is no guarantee that every calculation is right on all data. Linked sites are the responsibility of their operators.")}</p>
      <p><a href="#hilfe/ueber-statable">{L('Über Statable', 'About Statable')}</a></p>
  {:else if art === 'behoerden'}
    <SeitenKopf titelId="re-t" titel={L('Für Behörden und Rechenzentren', 'For public bodies and data centres')} zurueck />
      <p>{L("Dieses Blatt sammelt Angaben für Stellen, die Statable einsetzen wollen, zum Beispiel Behörden und Rechenzentren. Es ist keine Rechtsberatung. Was nicht belegt ist, steht als „offen“ oder „unbekannt“ da. Stand: 7. November 2026.", "This sheet collects information for bodies that want to use Statable, for example public authorities and data centres. It is not legal advice. Whatever is not backed by evidence is marked \"open\" or \"unknown\". As of November 7, 2026.")}</p>
      <p>{MELDEN_SERVER ? L("Diese Seite gehört zu einer Bauart mit Server: Melden und Besucherzählung sind eingebaut.", "This page belongs to a build with a server: reporting and visitor counting are built in.") : L("Diese Seite gehört zu einer Bauart ohne Server: Es gibt kein Melden über einen Server und keine Besucherzählung.", "This page belongs to a build without a server: there is no reporting through a server and no visitor counting.")}</p>
      <h2>{L("Wo die Daten liegen", "Where the data is")}</h2>
      <p>{L("Die Daten einer Auswertung liegen im Browser auf dem Gerät der Person (Browser-Datenbank und lokaler Speicher). Statable rechnet dort und schickt die Daten nicht an einen Server.", "The data of an analysis is in the browser on the person's own device (browser database and local storage). Statable calculates there and does not send the data to a server.")}</p>
      {#if !OFFLINE}
      <p>{L("Eine Ausnahme beim Aufruf, nicht bei den Daten: Beim Klick auf „Von Eurostat laden“ (Startseite, „Eurostat-Daten öffnen“) geht eine Anfrage an die Europäische Kommission (ec.europa.eu). Deren Server sieht dabei die IP-Adresse und die Abfrage (Datensatz und Filter). Sonst geht nichts dorthin; Daten aus Statable werden nicht gesendet. Ohne diesen Klick geht keine Anfrage hinaus. Ebenso beim Klick auf „Grenzen von Eurostat laden“ (Seite „Karte“): Dann geht eine Anfrage an gisco-services.ec.europa.eu, und deren Server sieht die IP-Adresse und die Adresse der Datei, sonst nichts; Daten aus Statable werden nicht gesendet. Die Offline-Fassung bietet beides nicht an.", "An exception when calling up, not for the data: clicking \"Load from Eurostat\" (start page, \"Open Eurostat data\") sends a request to the European Commission (ec.europa.eu). Its server sees the IP address and the query (dataset and filters). Nothing else goes there; no data from Statable is sent. Without this click no request is sent. The same applies when \"Load boundaries from Eurostat\" is clicked (page \"Map\"): then a request goes to gisco-services.ec.europa.eu, and its server sees the IP address and the address of the file, nothing else; no data from Statable is sent. The offline version offers neither.")}</p>
      {/if}
      <p>{L("Die Offline-Fassung läuft am Rechner ohne Internet (Windows, Mac, Linux) und braucht kein Netz. Sie wird nicht aktualisiert.", "The offline version runs on the computer without internet (Windows, Mac, Linux) and needs no network. It is not updated.")}</p>
      <h2>{L("Bauart ohne Server", "Build without a server")}</h2>
      <ul>
        <li>{L("Keine Besucherzählung und keine Meldestelle auf einem Server. „Melden“ öffnet das Mailprogramm der Person; was sie dort sendet, entscheidet sie selbst.", "No visitor counting and no reporting service on a server. \"Report\" opens the person's mail program; what is sent from there is the person's own decision.")}</li>
        <li>{L("Die Seite und alle Programmteile liegen auf dem Server, der sie ausliefert. Bei eigenem Betrieb ist das der Server der Stelle. Dieser Server sieht technisch die IP-Adresse der Anfrage.", "The page and all program parts are on the server that delivers them. When run by the body itself, this is the body's own server. That server technically sees the IP address of the request.")}</li>
      </ul>
      <h2>{L("Bauart mit Server (statable.eu)", "Build with a server (statable.eu)")}</h2>
      <ul>
        <li>{L("Hosting: Server der Hetzner Online GmbH in Deutschland (laut Datenschutzseite). Der Server schreibt laut Datenschutzseite keine Zugriffsprotokolle (im Caddyfile gemessen am 7. Oktober 2026).", "Hosting: server of Hetzner Online GmbH in Germany (according to the privacy page). According to the privacy page, the server writes no access logs (measured in the Caddyfile on October 7, 2026).")}</li>
        <li>{L("Melden: nur wenn die Person auf „Senden“ klickt. Dann gehen der Text, technische Angaben (Stand der App, Sprache, Seite, Fenstergröße, Browser), auf Wunsch ein Bild vom Fenster und eine freiwillige Antwortadresse an den Server von Statable. Dort werden sie gespeichert und als Mail an service@statable.eu weitergegeben. Die Daten der Auswertung gehen nicht mit; das Bild kann sie aber zeigen. Es ist vor dem Senden zu sehen und lässt sich abwählen.", "Reporting: only if the person clicks \"Send\". Then the text, technical details (version of the app, language, page, window size, browser), on request a picture of the window and a voluntary reply address go to the Statable server. There they are stored and passed on as an email to service@statable.eu. The data of the analysis does not go along, but the picture can show it. It can be seen before sending and can be switched off.")}</li>
        <li>{L("Besucherzählung: Starts der Seite, Dauer der aktiven Nutzung, Sprache, Art des Geräts, Name der verweisenden Website, gerechnete Verfahren, geöffnete Lerneinheiten, Lernpfade und Hilfeartikel (nur als Summe je Tag) und geladene Programmteile. Eine Zufallsnummer liegt im lokalen Speicher des Browsers (kein Cookie). Die IP-Adresse wird nicht gespeichert, nur eine Prüfsumme mit einem monatlich neuen Geheimwert, der spätestens nach zwei Monaten gelöscht wird. Die Zählwerte werden nach 25 Monaten gelöscht (nächtliches Aufräumen in server/pb_hooks/zaehlung.pb.js). Daten der Auswertung, Spaltennamen und Dateinamen gehen nie mit.", "Visitor counting: page starts, duration of active use, language, type of device, name of the referring website, methods calculated, learning units, learning paths and help articles opened (only as a daily total) and program parts loaded. A random number is kept in the browser's local storage (not a cookie). The IP address is not stored, only a checksum with a secret value that changes every month and is deleted after two months at the latest. The counts are deleted after 25 months (nightly clean-up in server/pb_hooks/zaehlung.pb.js). Analysis data, column names and file names are never sent.")}</li>
        <li>{@html L("Abschalter: Die Zählung lässt sich auf der <a href=\"#datenschutz\">Datenschutzseite</a> abschalten. Browser mit „Do Not Track“ oder „Global Privacy Control“ werden nicht gezählt.", "Switch-off: counting can be switched off on the <a href=\"#datenschutz\">privacy page</a>. Browsers with \"Do Not Track\" or \"Global Privacy Control\" are not counted.")}</li>
        {#if !OFFLINE}<li>{L("Spenden: Die Seite „Unterstützen“ verlinkt Zahlungsseiten von Stripe (neuer Tab, erst beim Klick geladen). Es wird keine Anfrage an Stripe gestellt, solange niemand klickt; die Content-Security-Policy ändert sich nicht. Nach 10 Stunden aktiver Nutzung (lokaler Zähler, kein Server) erscheint ein Hinweis; abschaltbar.", "Donations: the page \"Support\" links to payment pages of Stripe (new tab, loaded only on click). No request goes to Stripe unless someone clicks; the Content-Security-Policy does not change. After 10 hours of active use (local counter, no server) a notice appears; it can be switched off.")}</li>{/if}
      </ul>
      <h2>{L("Rolle", "Role")}</h2>
      <p>{L("Bei reinem Browser-Einsatz verarbeitet Statable keine Daten für die einsetzende Stelle: Die Daten bleiben auf deren Geräten. In der Bauart mit Server verarbeitet Statable beim Melden, bei der Besucherzählung und beim Teilen von Lernpfaden (Name und Einheiten des Pfads) die oben genannten Angaben. Eine rechtliche Einordnung dieser Rolle (Verantwortlicher oder Auftragsverarbeiter) steht hier nicht; sie ist offen.", "With pure use in the browser, Statable processes no data for the body using it: the data stays on its devices. In the build with a server, Statable processes the details named above when reporting, when counting visitors and when sharing learning paths (name and units of the path). A legal classification of this role (controller or processor) is not given here; it is open.")}</p>
      <h2>{L("Externe Adressen", "External addresses")}</h2>
      {#if !CSP_TEXT}
      <p>{L("Der Wortlaut der Content-Security-Policy ist in dieser Fassung nicht eingebaut (DEPLOY.md lag beim Bau nicht vor): unbekannt.", "The wording of the Content-Security-Policy is not built into this version (DEPLOY.md was not available at build time): unknown.")}</p>
      {:else}
      <p>{externe.length === 0 ? L("Die empfohlene Content-Security-Policy in DEPLOY.md nennt keine externe Adresse: Alle Quellen sind die eigene Adresse ('self'), data: oder blob:.", "The recommended Content-Security-Policy in DEPLOY.md names no external address: all sources are the own address ('self'), data: or blob:.") : L(`Die empfohlene Content-Security-Policy in DEPLOY.md nennt diese externen Adressen: ${externe.join(', ')}.`, `The recommended Content-Security-Policy in DEPLOY.md names these external addresses: ${externe.join(', ')}.`)}</p>
      {#if externe.includes('https://ec.europa.eu')}
      <p>{L("Die Adressen ec.europa.eu und gisco-services.ec.europa.eu dienen allein dem Laden von Eurostat-Daten und Eurostat-Grenzen auf Klick (siehe „Wo die Daten liegen“). Wer das nicht will, entfernt sie aus der Kopfzeile; die übrige App läuft dann weiter, nur das Laden von Eurostat scheitert mit einer Meldung.", "The addresses ec.europa.eu and gisco-services.ec.europa.eu serve only to load Eurostat data and Eurostat boundaries on click (see \"Where the data is\"). Whoever does not want that removes it from the header; the rest of the app then keeps running, only loading from Eurostat fails with a message.")}</p>
      {/if}
      <p>{L("Wortlaut, beim Bau aus DEPLOY.md gelesen (nicht von Hand kopiert):", "Wording, read from DEPLOY.md at build time (not copied by hand):")}</p>
      <p><code class="csp">{CSP_TEXT}</code></p>
      {/if}
      <p>{L("Das ist die Empfehlung aus DEPLOY.md. Was ein laufender Server tatsächlich sendet, steht hier nicht fest; die Kopfzeile lässt sich mit curl -sI prüfen. Für Antworten unter webr/ (Laufzeit von R) sieht DEPLOY.md zusätzlich 'unsafe-eval' in script-src vor.", "This is the recommendation from DEPLOY.md. What a running server actually sends is not established here; the header can be checked with curl -sI. For responses under webr/ (the R runtime), DEPLOY.md also provides 'unsafe-eval' in script-src.")}</p>
      <h2>{L("Technische Maßnahmen", "Technical measures")}</h2>
      <p>{L("Nur, was im Code belegt ist:", "Only what is backed by the code:")}</p>
      <ul>
        <li>{L(`Feste Versionen: npm-Pakete über die Sperrdatei package-lock.json; webR 0.6.0 mit Prüfsumme (SHA-256); ${RPAKETE.length} R-Pakete mit Prüfsumme je Paket (scripts/webr-pakete.sha256); PSPP 2.1.3 mit den Änderungen aus patches/.`, `Fixed versions: npm packages through the lock file package-lock.json; webR 0.6.0 with checksum (SHA-256); ${RPAKETE.length} R packages with a checksum for each (scripts/webr-pakete.sha256); PSPP 2.1.3 with the changes from patches/.`)}</li>
        <li>{L("Programmteile, R-Pakete und Schriften werden vom selben Server ausgeliefert; der Browser fragt dafür keinen fremden Server an (so beschrieben in scripts/webr-holen.sh und im Wortlaut der Content-Security-Policy oben).", "Program parts, R packages and fonts are delivered by the same server; the browser asks no third-party server for them (as described in scripts/webr-holen.sh and in the Content-Security-Policy wording above).")}</li>
        <li>{L("Text aus Dateien (Spaltennamen, Beschriftungen, Textwerte) wird nie als Befehl an R oder PSPP weitergegeben. Das prüfen Tests im Quelltext (engine/rsicher.test.ts, lib/befehlstext-pspp.test.ts).", "Text from files (column names, labels, text values) is never passed to R or PSPP as a command. Tests in the source code check this (engine/rsicher.test.ts, lib/befehlstext-pspp.test.ts).")}</li>
        <li>{L("Keine Cookies und keine Werbung (laut Datenschutzseite).", "No cookies and no ads (according to the privacy page).")}</li>
      </ul>
      <h2>{L("Unterlagen", "Documents")}</h2>
      {#if OFFLINE}
      <p>{L("Liste der Bestandteile und Prüfbericht gehören zu jeder Fassung auf statable.eu; diese Offline-Fassung enthält sie nicht.", "The list of components and the test report come with each version on statable.eu; this offline version does not contain them.")}</p>
      {:else}
      <p>{@html L("<a href=\"sbom.cdx.json\" download>Liste der Bestandteile</a> (Software-Stückliste, CycloneDX 1.6, JSON): npm-Pakete, PSPP mit den Änderungen, webR, R, die R-Pakete mit Prüfsummen und die Schriften. Lizenzen stehen nur dort, wo ein Beleg gelesen wurde; sonst steht „unknown“. Die Liste ist keine Zertifizierung.", "<a href=\"sbom.cdx.json\" download>List of components</a> (software bill of materials, CycloneDX 1.6, JSON): npm packages, PSPP with the changes, webR, R, the R packages with checksums and the fonts. Licenses appear only where evidence was read; otherwise it says \"unknown\". The list is not a certification.")}</p>
      <p>{@html L("<a href=\"pruefbericht.html\">Prüfbericht zu dieser Version</a>: Ergebnis der Testsuite mit Zahlen, gescheiterten und übersprungenen Tests und den Sollwert-Dateien samt Prüfsumme. Die Tests vergleichen die App mit R und weiteren Quellen an festen Beispielen. Sie beweisen nicht, dass jede Rechnung auf allen Daten richtig ist. Der Bericht ist keine Zertifizierung.", "<a href=\"pruefbericht.html\">Test report for this version</a>: result of the test suite with numbers, failed and skipped tests and the reference-value files with checksums. The tests compare the app with R and other sources on fixed examples. They do not prove that every calculation is correct on all data. The report is not a certification.")}</p>
      {/if}
      <p>{@html L("Quelltext: <a href=\"statable-quelltext.tar.gz\" download>statable-quelltext.tar.gz</a>. Lizenz: GNU General Public License, Text in der Datei LICENSE im Quelltext; Einzelheiten im <a href=\"#impressum\">Impressum</a>.", "Source code: <a href=\"statable-quelltext.tar.gz\" download>statable-quelltext.tar.gz</a>. License: GNU General Public License, text in the file LICENSE in the source code; details in the <a href=\"#impressum\">legal notice</a>.")}</p>
      <p>{@html L("Zitierung: Weingartner, J. (2026). <i>Statable: statistics in the browser for study and research</i> [Computersoftware]. Zenodo. <a href=\"https://doi.org/10.5281/zenodo.23627103\" rel=\"noopener\">https://doi.org/10.5281/zenodo.23627103</a>", "Citation: Weingartner, J. (2026). <i>Statable: statistics in the browser for study and research</i> [Computer software]. Zenodo. <a href=\"https://doi.org/10.5281/zenodo.23627103\" rel=\"noopener\">https://doi.org/10.5281/zenodo.23627103</a>")}</p>
      <h2>{L("Textbaustein für das Verzeichnis der Verarbeitungstätigkeiten", "Text module for the record of processing activities")}</h2>
      <p>{L("Entwurf für die Bauart ohne Server. Felder in eckigen Klammern füllt die Stelle selbst aus. Keine Rechtsberatung.", "Draft for the build without a server. Fields in square brackets are to be filled in by the body itself. Not legal advice.")}</p>
      <ul>
        <li>{L("Bezeichnung: Statistische Auswertung mit Statable (Browser-Anwendung).", "Name: statistical analysis with Statable (browser application).")}</li>
        <li>{L("Zweck: [von der Stelle auszufüllen].", "Purpose: [to be filled in by the body].")}</li>
        <li>{L("Kategorien betroffener Personen und von Daten: [von der Stelle auszufüllen; richtet sich nach den ausgewerteten Daten].", "Categories of data subjects and of data: [to be filled in by the body; depends on the data analysed].")}</li>
        <li>{L("Art der Verarbeitung: im Browser auf dem Gerät der Nutzerin oder des Nutzers; die Daten werden nicht an Statable übertragen.", "Kind of processing: in the browser on the user's own device; the data is not transmitted to Statable.")}</li>
        {#if OFFLINE}<li>{L("Empfänger: durch Statable keine. [Weitere Empfänger: von der Stelle auszufüllen.]", "Recipients: none through Statable. [Further recipients: to be filled in by the body.]")}</li>
        {:else}<li>{L("Empfänger: durch Statable keine, außer beim Klick auf „Von Eurostat laden“: Dann erhält die Europäische Kommission die IP-Adresse und die Abfrage (Datensatz und Filter), keine Daten aus Statable. Dasselbe gilt beim Klick auf „Grenzen von Eurostat laden“: IP-Adresse und Adresse der Datei. [Weitere Empfänger: von der Stelle auszufüllen.]", "Recipients: none through Statable, except when \"Load from Eurostat\" is clicked: then the European Commission receives the IP address and the query (dataset and filters), no data from Statable. The same applies when \"Load boundaries from Eurostat\" is clicked: IP address and address of the file. [Further recipients: to be filled in by the body.]")}</li>{/if}
        <li>{L("Übermittlung in ein Drittland: durch Statable keine. [Von der Stelle zu prüfen.]", "Transfer to a third country: none through Statable. [To be checked by the body.]")}{#if !OFFLINE} {L("Die Anfrage an Eurostat geht an die Europäische Kommission; der Standort ihres Servers ist hier nicht festgestellt.", "The request to Eurostat goes to the European Commission; the location of its server is not established here.")}{/if}</li>
        <li>{L("Löschfristen: Die Daten liegen im Browser, bis die Person sie löscht oder die Websitedaten entfernt. [Frist legt die Stelle fest.]", "Retention periods: the data stays in the browser until the person deletes it or removes the site data. [The body sets the period.]")}</li>
        <li>{L("Technische und organisatorische Maßnahmen: siehe oben „Technische Maßnahmen“ [und die der Stelle].", "Technical and organisational measures: see \"Technical measures\" above [and those of the body].")}</li>
      </ul>
      <h2>{L("Wartung", "Maintenance")}</h2>
      <p>{L("Das Projekt hängt derzeit an einer Person: Der Git-Verlauf nennt einen Autor. Server, Adresse statable.eu, Veröffentlichung neuer Fassungen und das Postfach service@statable.eu liegen bei dieser Person. Der Quelltext ist offen (GPL), und Statable läuft als statische Dateien ohne Server; nur Melden und Besucherzählung brauchen einen.", "The project currently depends on one person: the Git history names one author. The server, the address statable.eu, publishing new versions and the mailbox service@statable.eu are with this person. The source code is open (GPL), and Statable runs as static files without a server; only reporting and visitor counting need one.")}</p>
      <h2>{L("Offen", "Open")}</h2>
      <p>{L("Diese Punkte sind nicht entschieden und nicht belegt. Sie stehen hier als „offen“, damit nichts erfunden wird:", "These points are not decided and not backed by evidence. They are listed as \"open\" so that nothing is made up:")}</p>
      <ul>
        <li>{L("Hostingvertrag und Auftragsverarbeitung mit der Hetzner Online GmbH: offen.", "Hosting contract and data processing agreement with Hetzner Online GmbH: open.")}</li>
        <li>{L("Reaktionszeit bei Sicherheitsmeldungen: offen.", "Response time for security reports: open.")}</li>
        <li>{L("Updatepolitik (wie oft, wie lange gepflegt): offen.", "Update policy (how often, for how long maintained): open.")}</li>
        <li>{L("Löschfristen der Meldungen: offen. Im Code löscht nichts die Meldungen von selbst; auf Wunsch werden sie per Mail gelöscht.", "Retention periods of reports: open. Nothing in the code deletes the reports by itself; on request they are deleted by email.")}</li>
        <li>{L("Ansprechstelle für Behörden: offen. Bisher gibt es nur service@statable.eu, keinen eigenen Weg für Sicherheitsmeldungen.", "Contact point for public bodies: open. So far there is only service@statable.eu and no separate route for security reports.")}</li>
      </ul>
      <p>{L("Das ist keine Rechtsberatung.", "This is not legal advice.")}</p>
      <h2>{L("Barrierefreiheit", "Accessibility")}</h2>
      <p>{@html L("Die Erklärung zur Barrierefreiheit steht auf einer eigenen Seite: <a href=\"#barrierefreiheit\">Erklärung zur Barrierefreiheit</a>. Status: teilweise vereinbar.", "The accessibility statement is on a page of its own: <a href=\"#barrierefreiheit\">Accessibility statement</a>. Status: partially conformant.")}</p>
  {:else if art === 'barrierefreiheit'}
    <SeitenKopf titelId="re-t" titel={L('Erklärung zur Barrierefreiheit', 'Accessibility statement')} zurueck />
      <p>{L("Statable ist bemüht, die Website statable.eu (die Statistik-Anwendung im Browser, die Hilfe-Artikel und die Offline-Fassung) für alle Menschen zugänglich zu machen, auch für Menschen, die ohne Maus arbeiten, einen Screenreader oder eine Braillezeile benutzen. Stand dieser Erklärung: 7. November 2026.", "Statable is trying to make the website statable.eu (the statistics application in the browser, the help articles and the offline version) accessible to everyone, including people who work without a mouse or use a screen reader or a braille display. Date of this statement: 7 November 2026.")}</p>
      <p>{L("Zur rechtlichen Lage: Das Web-Zugänglichkeits-Gesetz (WZG), BGBl. I Nr. 59/2019, verpflichtet den Bund und bestimmte bundesnahe Einrichtungen. Statable ist ein privates, nicht-kommerzielles Angebot und fällt nach dem Stand der Prüfung vom 30. Oktober 2026 selbst nicht darunter. Rechtlich gewiss ist das nicht. Eine Stelle, die Statable auf ihrer eigenen Website anbietet oder Beschäftigten bereitstellt, kann für ihr Angebot betroffen sein. Diese Erklärung folgt dem österreichischen Muster freiwillig. Sie ist keine Rechtsberatung.", "On the legal situation: the Austrian Web Accessibility Act (WZG), Federal Law Gazette I No. 59/2019, obliges the federal government and certain related bodies. Statable is a private, non-commercial service and, as of the review of 30 October 2026, does not fall under it itself. This is not legally certain. A body that offers Statable on its own website or provides it to its staff may be affected for its own offer. This statement follows the Austrian model voluntarily. It is not legal advice.")}</p>
      <p>{L("Die Erklärung gilt für statable.eu. Dateien, die Statable erzeugt (Word, Excel, PDF), sind in den Abschnitten „Was geht“ und „Bekannte Grenzen“ beschrieben. Nicht erfasst sind Bilder, die Statable erzeugt (PNG-Export), Plakate und Dateien, die Nutzende selbst hochladen.", "The statement applies to statable.eu. Files that Statable creates (Word, Excel, PDF) are described in the sections “What works” and “Known limits”. Not covered are images that Statable creates (PNG export), posters and files that users upload themselves.")}</p>
      <h2>{L("Stand der Vereinbarkeit", "Status of conformance")}</h2>
      <p>{L("Diese Website ist teilweise vereinbar mit der Konformitätsstufe AA der Richtlinien für barrierefreie Webinhalte (WCAG) 2.2. Maßstab der Prüfung sind die 51 Zeilen der Prüftabelle zu den Erfolgskriterien der WCAG 2.2, Stufe AA (die Kriterien der WCAG 2.1 sind darin enthalten und sind Grundlage des europäischen Standards EN 301 549 V3.2.1).", "This website is partially conformant with conformance level AA of the Web Content Accessibility Guidelines (WCAG) 2.2. The yardstick of the check is the 51 rows of the table of success criteria of WCAG 2.2, level AA (the criteria of WCAG 2.1 are included and are the basis of the European standard EN 301 549 V3.2.1).")}</p>
      <ul>
        <li>{L("36 Zeilen sind erfüllt (mit Beleg; bei 14 davon ist der Beleg eine Prüfung des Quelltextes oder das Protokoll von NVDA, nicht von einem Menschen gehört).", "36 rows are met (with evidence; for 14 of them the evidence is a check of the source code or the NVDA log, not heard by a person).")}</li>
        <li>{L("1 Zeile ist nicht erfüllt (3.1.2, teilweise).", "1 row is not met (3.1.2, partly).")}</li>
        <li>{L("11 Zeilen sind nicht gemessen.", "11 rows have not been measured.")}</li>
        <li>{L("3 Zeilen treffen nicht zu (keine Medien, kein Ton, keine Bewegungssteuerung).", "3 rows do not apply (no media, no sound, no motion control).")}</li>
      </ul>
      <p>{L("Weil eine Zeile nicht erfüllt und 11 Zeilen nicht gemessen sind, ist Statable teilweise vereinbar. Eine vollständige Prüfung liegt nicht vor.", "Because one row is not met and 11 rows have not been measured, Statable is partially conformant. A complete check has not been done.")}</p>
      <h2>{L("Was gemessen wurde", "What was measured")}</h2>
      <ul>
        <li>{L("Screenreader: NVDA 2026.3 mit Microsoft Edge am Windows-PC, am 6. und 7. November 2026 an Fachwörtern, Dialogen, Tab-Folge, Kürzeln, Tabellen (auch Kreuztabelle und Datentabelle), Diagrammen, Lernen, Üben, Hilfe, Reglern und Ansagen; nach den Behebungen vom 7. November lief eine dritte Messreihe. Es wurde das Sprachprotokoll von NVDA gelesen, nicht von einem Menschen gehört. Die Braillezeile wurde nur über eine Datei im Prüfstand nachgebildet, nicht an einer echten Zeile.", "Screen reader: NVDA 2026.3 with Microsoft Edge on a Windows PC, on 6 and 7 November 2026 on technical terms, dialogs, tab order, shortcuts, tables (including the crosstab and the data table), charts, Learn, Practise, help, sliders and announcements; after the fixes of 7 November a third series of measurements was run. The speech log of NVDA was read; it was not listened to by a person. The braille display was only simulated through a file in the test rig, not on a real display.")}</li>
        <li>{L("Browser: Chromium (Playwright), Sprache Deutsch, Fenster 1280 x 800, Beispiel geöffnet, 40 Seiten mit dem Prüfwerkzeug axe-core (Normalmodus und emulierter Kontrastmodus), der Tab-Weg auf 27 und auf 15 weiteren Seiten, Kontrast auf 39 Seiten in sieben Themen, Nicht-Text-Kontrast, Zielgröße, Konsistenz von Kopf und Namen auf 16 Seiten, Zoom und Reflow (320 x 640, Fenster 640 für 200 %, Hoch- und Querformat, Textabstand nach 1.4.12), Seitentitel, Sprache der Seite, Hilfe und Melden im Kopf; Kürzel und Fokus in Edge und Chrome.", "Browser: Chromium (Playwright), German, window 1280 x 800, example opened, 40 pages with the testing tool axe-core (normal mode and emulated contrast mode), the tab path on 27 and on 15 further pages, contrast on 39 pages in seven themes, non-text contrast, target size, consistency of the header and of names on 16 pages, zoom and reflow (320 x 640, window 640 for 200%, portrait and landscape, text spacing according to 1.4.12), page titles, language of the page, help and report in the header; shortcuts and focus in Edge and Chrome.")}</li>
        <li>{L("Windows-Kontrastmodus: am echten Windows (Edge, Thema Nachthimmel) nur eine Stichprobe: 24 Tab-Stopps auf vier Seiten zeigen einen durchgehenden Fokusrahmen in Systemfarbe. Sonst nur der Kontrastmodus, den der Browser nachahmt.", "Windows contrast mode: on a real Windows (Edge, theme Night sky) only a sample: 24 tab stops on four pages show a continuous focus frame in the system colour. Otherwise only the contrast mode imitated by the browser.")}</li>
        <li>{L("Dazu die Durchsicht des Quelltextes und Wächter-Tests, die bei jedem Bau laufen (zum Beispiel für Fokusrahmen, Tabellenköpfe, Tastenkürzel, Ansagen und die Exporte).", "In addition a review of the source code and guard tests that run on every build (for example for focus frames, table headers, keyboard shortcuts, announcements and the exports).")}</li>
        <li>{L("Das ist eine Selbstbewertung des Betreibers. Eine Bewertung durch Dritte liegt nicht vor. Einzelheiten und Zahlen stehen im Quelltext in docs/barrierefreiheit/ABSCHLUSS.md.", "This is a self-assessment by the operator. There is no assessment by third parties. Details and figures are in the source code in docs/barrierefreiheit/ABSCHLUSS.md.")}</li>
      </ul>
      <h2>{L("Was geht", "What works")}</h2>
      <ul>
        <li>{@html L("Tastatur: Ein Sprunglink „Zum Inhalt springen“ steht als erster Tab-Stopp. Auf 27 gemessenen Seiten führt Tab ohne Tastaturfalle einmal rundherum, kein Stopp ist ohne Namen, kein Stopp liegt ganz verdeckt. Alle Tastenkürzel (Liste mit Alt+T, Befehlspalette mit Strg+K) brauchen Strg oder Alt; Einzeltasten gelten nur im Fragebereich der Übungen. Beschrieben in <a href=\"#hilfe/barrierefrei-bedienen\">Statable ohne Maus und mit Screenreader</a>.", "Keyboard: a skip link “Skip to content” is the first tab stop. On 27 measured pages Tab goes once around without a keyboard trap, no stop is without a name, no stop is completely covered. All keyboard shortcuts (list with Alt+T, command palette with Ctrl+K) need Ctrl or Alt; single keys apply only in the question area of the exercises. Described in <a href=\"#hilfe/barrierefrei-bedienen\">Statable without a mouse and with a screen reader</a>.")}</li>
        <li>{L("Fokus und Farben: Der Fokus ist an allen gemessenen Tab-Stopps sichtbar. Fünf Farbwahlen mit starkem Kontrast stehen im Kopf („Farben und Kontrast“, Alt+K).", "Focus and colours: the focus is visible at all measured tab stops. Five colour choices with strong contrast are in the header (“Colors and contrast”, Alt+K).")}</li>
        <li>{L("Größe: Bei 320 x 640 Pixeln, bei einem Fenster von 640 Pixeln (entspricht 200 % Zoom auf 1280 Pixeln) und im Hoch- und Querformat gibt es auf den 27 gemessenen Seiten kein waagrechtes Scrollen. Mit dem Textabstand aus 1.4.12 wird kein Text neu abgeschnitten.", "Size: at 320 x 640 pixels, with a window of 640 pixels (equals 200% zoom at 1280 pixels) and in portrait and landscape there is no horizontal scrolling on the 27 measured pages. With the text spacing from 1.4.12 no text is newly cut off.")}</li>
        <li>{L("Tabellen und Diagramme: Ergebnistabellen haben Kopfzellen mit Zuordnung; ein Schalter in den Einstellungen setzt kurze Spaltenköpfe (SD, SE, p) mit Abkürzungsliste. Die Datentabelle hat einen Lesemodus mit festen Seiten zu 50 Zeilen. Unter jedem Diagramm steht „Beschreibung und Daten“ (Text und Tabelle).", "Tables and charts: result tables have header cells with association; a switch in the settings sets short column headers (SD, SE, p) with a list of abbreviations. The data table has a reading mode with fixed pages of 50 rows. Under every chart there is “Description and data” (text and table).")}</li>
        <li>{L("Ausgabe: Word-Dateien mit Überschriften, Tabellenköpfen und Alternativtexten, Excel mit Tabellen und Blattnamen, ein PDF über die Druckansicht des Browsers mit Dokumentaufbau. Der Word-Bericht wurde in Word (Titel, Überschriften, Tabellenkopf, Alternativtext) und die Excel-Datei in Excel (Blattnamen, Tabellenkopf) geöffnet und gelesen, dazu mit Wächter-Tests geprüft; die Funktion „Barrierefreiheit überprüfen“ von Word und NVDA in Word und Excel sind nicht gemessen.", "Output: Word files with headings, table headers and alternative texts, Excel with tables and sheet names, a PDF through the print view of the browser with document structure. The Word report was opened and read in Word (title, headings, table header, alternative text) and the Excel file in Excel (sheet names, table header), and checked with guard tests; the “Check accessibility” function of Word and NVDA in Word and Excel are not measured.")}</li>
        <li>{L("Word-Bericht: Der Schalter „Bildbeschreibungen im Text“ (im Bericht und in den Einstellungen) legt fest, ob nach jedem Diagramm die Beschreibung und die Datentabelle im Text stehen; der Alternativtext am Bild bleibt immer.", "Word report: the switch “Image descriptions in the text” (in the report and in the settings) decides whether the description and the data table follow each chart in the text; the alternative text on the image always stays.")}</li>
        <li>{L("Sprache und Titel: Die Sprache der Seite (lang) folgt der Wahl, gemessen für Deutsch, Englisch und Ukrainisch. Jede der 25 geprüften Seiten hat einen Titel. Hilfe und Melden stehen im Kopf auf jeder Seite an derselben Stelle.", "Language and title: the language of the page (lang) follows the choice, measured for German, English and Ukrainian. Each of the 25 pages checked has a title. Help and Report are in the same place in the header on every page.")}</li>
        <li>{L("Meldungen: Einfache Meldungen verschwinden nach 7 Sekunden, Meldungen mit „Rückgängig“ nach 14 bis 15 Sekunden; Zeiger oder Fokus auf der Meldung halten die Uhr an, Fehlermeldungen bleiben bis zum Schließen. Die letzten Meldungen stehen im Meldungsverlauf (Alt+M) und in der Befehlspalette; „Rückgängig“ geht auch mit Strg+Z.", "Messages: simple messages disappear after 7 seconds, messages with “Undo” after 14 to 15 seconds; the pointer or focus on the message stops the clock, error messages stay until they are closed. The latest messages are in the message history (Alt+M) and in the command palette; “Undo” also works with Ctrl+Z.")}</li>
      </ul>
      <h2>{L("Bekannte Grenzen", "Known limits")}</h2>
      <p>{L("Nicht erfüllt ist zurzeit dieses Kriterium (teilweise):", "This criterion is currently not met (partly):")}</p>
      <ul>
        <li>{L("3.1.2 Sprache von Teilen: In Hilfe-Artikeln, Hilfe-Titeln, Begriffs-Überschriften und Suchtreffern sind englische Fachwörter in Klammern mit lang ausgezeichnet. In festen Texten der Seiten (zum Beispiel „Joint Display“, „Random Effects“, „Leave-one-out“) fehlt die Auszeichnung noch bei rund 19 Fachwörtern; Ergebnissätze nach einer Rechnung und Übungsfragen sind nicht gemessen.", "3.1.2 Language of parts: in help articles, help titles, term headings and search hits, English technical terms in brackets are marked with lang. In fixed texts of the pages (for example “Joint Display”, “Random Effects”, “Leave-one-out”) the marking is still missing for about 19 technical terms; result sentences after a calculation and practice questions are not measured.")}</li>
      </ul>
      <p>{L("Weitere bekannte Einschränkungen:", "Other known restrictions:")}</p>
      <ul>
        <li>{L("PDF: Jedes PDF entsteht über die Druckansicht („Als PDF (über Drucken)“); einen Weg ohne Dokumentaufbau gibt es seit 10. November 2026 nicht mehr. Das PDF hat Dokumentaufbau, Titel, Sprache, Überschriften und Tabellenköpfe. Der Prüfer PAC 2026 (Standard PDF/UA-1) meldete am 7. November 2026 an einem so erzeugten Bericht Fehler (unter anderem Metadaten, Tabellenüberschriften, Alternativtexte); das PDF ist damit nicht PDF/UA-konform, und der Browser schreibt die Kennung PDF/UA nicht. Seitdem ist der Aufbau von Bildern und Tabellen im Druck-HTML verbessert, PAC lief danach nicht erneut. Der barrierefreie Weg für einen Bericht ist der Word-Bericht.", "PDF: every PDF is made via the print view (“As PDF (via Print)”); since 10 November 2026 there is no longer a route without document structure. The PDF has document structure, title, language, headings and table headers. The checker PAC 2026 (standard PDF/UA-1) reported errors on a report produced this way on 7 November 2026 (among others metadata, table captions, alternative texts); the PDF is therefore not PDF/UA conformant, and the browser does not write the PDF/UA identifier. Since then the structure of images and tables in the print HTML has been improved; PAC was not run again afterwards. The accessible route for a report is the Word report.")}</li>
        <li>{L("Diagramme: Die Beschreibungstexte der Diagramme entstehen nach festen Regeln aus den Zahlen. Sie sind nicht von Hand geschrieben und beschreiben ein Muster nur grob. Die Zahlen stehen in der Tabelle darunter.", "Charts: the description texts of the charts are produced by fixed rules from the numbers. They are not written by hand and describe a pattern only roughly. The numbers are in the table below.")}</li>
        <li>{L("Kontrastmodus: Gemessen ist nur der Fokus im Thema Nachthimmel am echten Windows (Stichprobe). Das Thema Wüste ist nicht gemessen. Die vielen Kontrastmeldungen von axe im vom Browser nachgeahmten Kontrastmodus sind ein Messartefakt (axe rechnet mit den Farben der Seite, der Browser zeigt Systemfarben; die berechneten Farben erreichen mindestens 4,5 zu 1). Im Normalmodus meldet axe in allen sieben Themen keinen Kontrastverstoß; 186 Knoten je Thema (meist Zierde) sind unklar und nicht von Hand geklärt.", "Contrast mode: only the focus in the theme Night sky on a real Windows is measured (sample). The theme Desert is not measured. The many contrast reports from axe in the contrast mode imitated by the browser are a measurement artefact (axe calculates with the colours of the page, the browser shows system colours; the computed colours reach at least 4.5 to 1). In normal mode axe reports no contrast violation in all seven themes; 186 nodes per theme (mostly decoration) are unclear and have not been clarified by hand.")}</li>
        <li>{L("Fachwörter in Überschriften und in den auf- und zuklappbaren Überschriftszeilen (summary) sind nicht anklickbar, damit ein Screenreader die Überschrift als ein Stück liest. Dasselbe Fachwort steht im Text darunter und ist dort anklickbar; die Erklärung steht auch im Glossar der Hilfe.", "Technical terms in headings and in the collapsible heading lines (summary) are not clickable, so that a screen reader reads the heading as one piece. The same term appears in the text below and is clickable there; the explanation is also in the glossary of the help.")}</li>
        <li>{L("Dialoge (Melden, Befehlspalette, Tastenkürzel): Mit NVDA: Esc zweimal drücken. Das erste Esc beendet in einem Textfeld den Fokusmodus von NVDA, erst das zweite Esc schließt den Dialog (so gemessen). Das ist das Verhalten von NVDA, nicht der App; ohne Screenreader schließt schon ein Esc.", "Dialogs (Report, command palette, keyboard shortcuts): with NVDA, press Esc twice. The first Esc in a text field ends NVDA's focus mode; only the second Esc closes the dialog (as measured). This is the behaviour of NVDA, not of the app; without a screen reader one Esc already closes it.")}</li>
        <li>{L("Nach den Behebungen vom 7. November 2026 (Tabellenname, Fachwörter in Überschriften, Datentabelle, Regler, Hilfe-Trefferliste, Eckzelle) wurde im Browser neu gemessen und mit NVDA wiederholt (dritte Messreihe). Was danach behoben wurde (Hilfe-Ansage nach Enter auf einen Treffer, Hinweis in Üben, Kartensuche, Vorschau der Assistenten), ist mit NVDA noch nicht wiederholt.", "After the fixes of 7 November 2026 (table name, technical terms in headings, data table, sliders, help hit list, corner cell) new measurements were made in the browser and repeated with NVDA (third series). What was fixed afterwards (help announcement after Enter on a hit, hint in Practise, card search, preview of the assistants) has not yet been repeated with NVDA.")}</li>
      </ul>
      <h2>{L("Nicht geprüft", "Not checked")}</h2>
      <ul>
        <li>{L("Mit NVDA nicht gemessen sind alle Ansagen, die später als etwa eine Sekunde nach einer Taste kommen, besonders die Ansagen langer Rechnungen: In der Messkette stehen sie nicht im Protokoll, ob NVDA sie im Alltag spricht, ist nicht belegt. Alles andere wurde nur im Protokoll der Sprachausgabe gelesen, nicht von einem Menschen gehört. Kreuztabelle, Datentabelle, „Zurück zur Trefferliste“ und die Zeichen η², R², χ², M und SD sind im Protokoll gemessen; χ², R² und η² liest NVDA in Spaltenköpfen und im Fließtext als „hochgestellte 2“, der Tabellentitel „×“ als „Kreuz“. Das ist eine dokumentierte Grenze, kein Fehler im Aufbau.", "Not measured with NVDA are all announcements that come later than about one second after a key press, especially the announcements of long calculations: in the measuring chain they do not appear in the log, so it is not shown whether NVDA speaks them in everyday use. Everything else was only read in the speech log, not heard by a person. The crosstab, the data table, “Back to the hit list” and the symbols η², R², χ², M and SD are measured in the log; NVDA reads χ², R² and η² in column headers and in running text as “superscript 2”, and the table title “×” as “times”. This is a documented limit, not a structural error.")}</li>
        <li>{L("Nicht geprüft: JAWS, VoiceOver (Mac, iPhone, iPad), TalkBack, Firefox, Safari, Chrome mit NVDA, eine echte Braillezeile und Bildschirmlupen. Chrome ist ohne Screenreader für Kürzel und Fokus gemessen.", "Not checked: JAWS, VoiceOver (Mac, iPhone, iPad), TalkBack, Firefox, Safari, Chrome with NVDA, a real braille display and screen magnifiers. Chrome is measured without a screen reader for shortcuts and focus.")}</li>
        <li>{L("Andere Sprachen: Seitentitel, Namen und Tab-Weg sind nur auf Deutsch gemessen, die Sprache der Seite für Deutsch, Englisch und Ukrainisch. Die übrigen Sprachen sind nicht einzeln geprüft.", "Other languages: page titles, names and tab path are measured only in German, the language of the page for German, English and Ukrainian. The other languages have not been checked one by one.")}</li>
        <li>{L("Nur auf Deutsch, in Chromium und im hellen Thema gemessen sind der Tab-Weg und die Namen; Kontrast und Nicht-Text-Kontrast sind in allen sieben Themen gemessen. Nicht gemessen sind (11 Kriterien): die Reihenfolge von Fokus und Lesen (1.3.2, 2.4.3), Farbe als einziges Merkmal bei Ergebnis-Diagrammen (1.4.1), Umfließen nach der Behebung der Karte in den Einstellungen und ein nicht benanntes abgeschnittenes Element auf der Startseite bei 320 Pixeln (1.4.10), Inhalt bei Zeiger oder Fokus außer den Hinweisen (1.4.13), Tastenweg für jede Zeigerbedienung (2.1.1), Linkzweck im Kontext (2.4.4), Überschriften auf Sinn (2.4.6), Fehlervermeidung bei löschenden Handlungen (3.3.4), die Anmeldung der Betreiberseite (3.3.8) und die Sprache der Ansagen (4.1.3).", "Only in German, in Chromium and in the light theme are the tab path and the names measured; contrast and non-text contrast are measured in all seven themes. Not measured (11 criteria): the order of focus and reading (1.3.2, 2.4.3), colour as the only cue in result charts (1.4.1), reflow after the fix of the card in the settings and an unnamed cut-off element on the start page at 320 pixels (1.4.10), content on pointer or focus apart from the hints (1.4.13), a keyboard path for every pointer operation (2.1.1), link purpose in context (2.4.4), headings checked for sense (2.4.6), error prevention for deleting actions (3.3.4), the login of the operator page (3.3.8) and the language of the announcements (4.1.3).")}</li>
      </ul>
      <h2>{L("Barriere melden", "Report a barrier")}</h2>
      <p>{@html L("Bitte melden Sie Mängel bei der Barrierefreiheit oder Inhalte, die Sie nicht nutzen können. In Statable gibt es dafür den Knopf „Melden“ im Kopf (Tastenkürzel Alt+Umschalt+P) mit der Auswahl „Ich habe eine Barriere gefunden“. Oder schreiben Sie an <a href=\"mailto:service@statable.eu\">service@statable.eu</a>. Eine Antwortzeit ist nicht zugesagt. Zuständig ist der Betreiber, Johannes Weingartner, Königstetten, Österreich (siehe <a href=\"#impressum\">Impressum</a>).", "Please report accessibility defects or content you cannot use. In Statable there is the “Report” button in the header (shortcut Alt+Shift+P) with the choice “I found an accessibility barrier”. Or write to <a href=\"mailto:service@statable.eu\">service@statable.eu</a>. No response time is promised. The operator is responsible: Johannes Weingartner, Königstetten, Austria (see <a href=\"#impressum\">legal notice</a>).")}</p>
      <p>{L("Wer ein Ergebnis nicht lesen kann, kann es als Word, Excel oder PDF speichern und in einem anderen Programm lesen.", "Anyone who cannot read a result can save it as Word, Excel or PDF and read it in another program.")}</p>
      <h2>{L("Durchsetzung", "Enforcement")}</h2>
      <p>{L("Das Beschwerdeverfahren bei der Beschwerdestelle der Österreichischen Forschungsförderungsgesellschaft (FFG) gilt nach dem Muster für den Bund und ihm zuordenbare Einrichtungen. Weil das Web-Zugänglichkeits-Gesetz Statable selbst nach dem oben Gesagten wohl nicht erfasst, ist offen, ob und wie dieses Verfahren für Statable gilt.", "The complaints procedure at the complaints office of the Austrian Research Promotion Agency (FFG) applies under the model to the federal government and bodies attributable to it. Because the Web Accessibility Act, as said above, probably does not cover Statable itself, it is open whether and how this procedure applies to Statable.")}</p>
      <h2>{L("Erstellung dieser Erklärung", "How this statement was prepared")}</h2>
      <p>{L("Diese Erklärung wurde am 6. November 2026 erstellt. Grundlage ist die Selbstbewertung des Betreibers: die Messungen und die Prüftabelle in docs/barrierefreiheit (ABSCHLUSS.md und WCAG-2.2-AA.md im Quelltext). Zuletzt überprüft am 7. November 2026.", "This statement was prepared on 6 November 2026. It is based on the operator's self-assessment: the measurements and the table of criteria in docs/barrierefreiheit (ABSCHLUSS.md and WCAG-2.2-AA.md in the source code). Last reviewed on 7 November 2026.")}</p>
  {:else}
    <SeitenKopf titelId="re-t" titel={L('Datenschutz', 'Privacy')} zurueck />
      <h2>{L("Kurz gesagt", "In short")}</h2>
      {#if MELDEN_SERVER}
      <ul>{@html L("<li>Die Daten bleiben im Browser auf dem eigenen Gerät. Statable rechnet dort und schickt keine Daten an einen Server. Die einzige Ausnahme ist der Knopf „Melden“, wenn jemand ihn benutzt (siehe unten). Beim Teilen eines Lernpfads gehen nur sein Name und seine Einheiten an den Server, damit ein kurzer Link entsteht.</li><li>Keine Konten, keine Cookies, keine Werbung. Statable zählt Besuche auf dem eigenen Server, ohne fremde Dienste; die Zählung lässt sich abschalten (siehe unten).</li>", "<li>Your data stays in the browser on your own device. Statable calculates there and sends no data to any server. The only exception is the \"Report\" button, if someone uses it (see below). When a learning path is shared, only its name and units go to the server so that a short link can be created.</li><li>No accounts, no cookies, no ads. Statable counts visits on its own server, without third-party services; counting can be switched off (see below).</li>")}{@render fremdeDienste()}</ul>
      {:else}
      <ul>{@html L("<li>Die Daten bleiben im Browser auf dem eigenen Gerät. Statable rechnet dort und schickt keine Daten an einen Server.</li><li>Keine Konten, keine Cookies, keine Werbung, keine Zählung von Besuchen.</li>", "<li>Your data stays in the browser on your own device. Statable calculates there and sends no data to any server.</li><li>No accounts, no cookies, no ads, no visitor counting.</li>")}{@render fremdeDienste()}</ul>
      {/if}
      <p>{@html L("Erstellt von Johannes Weingartner mit Hilfe von Claude Code<br>Königstetten, Österreich<br><a href=\"https://statable.eu\">statable.eu</a><br> <a href=\"mailto:service@statable.eu\">service@statable.eu</a>", "Made by Johannes Weingartner with the help of Claude Code<br>Königstetten, Austria<br><a href=\"https://statable.eu\">statable.eu</a><br> <a href=\"mailto:service@statable.eu\">service@statable.eu</a>")}</p>
      <h2>{L("Was im Browser gespeichert wird", "What is stored in the browser")}</h2>
      <ul>{@html L("<li><strong>Einstellungen</strong> (Sprache, Farben, Anrede, Zahlen) - im lokalen Speicher des Browsers.</li><li><strong>Das offene Projekt</strong> (Daten, Fragen, Bericht) - in der Browser-Datenbank, damit die Arbeit beim nächsten Öffnen weitergeht.</li><li><strong>Die Programmdateien</strong> - damit Statable schnell startet und ohne Netz läuft.</li>", "<li><strong>Settings</strong> (language, colors, numbers) - in the browser's local storage.</li><li><strong>The open project</strong> (data, questions, report) - in the browser database, so you can continue next time.</li><li><strong>The program files</strong> - so Statable starts quickly and works offline.</li>")}{@html L("<li><strong>Der Lernstand</strong> (welche Einheiten im Bereich „Lernen“ durchgemacht, übersprungen oder offen sind, und welche Fragen richtig beantwortet wurden) - im lokalen Speicher des Browsers, nicht auf einem Server und nicht in der Projektdatei.</li>", "<li><strong>Your learning progress</strong> (which units in the area \"Learning\" are completed, skipped or open, and which questions were answered correctly) - in the browser's local storage, not on a server and not in the project file.</li>")}</ul>
      <p>{@html L("Das alles liegt nur auf dem eigenen Gerät. Löschen: in den Browser-Einstellungen die Websitedaten dieser Seite entfernen.", "All of this stays on your device only. To delete it, remove this site's data in your browser settings.")}</p>
      {#if !OFFLINE}
      <h2>{L("Wenn Grenzen von Eurostat für die Karte geladen werden", "When boundaries are loaded from Eurostat for the map")}</h2>
      <p>{L("Beim Klick auf „Grenzen von Eurostat laden“ (Seite „Karte“) geht eine Anfrage an die Europäische Kommission (gisco-services.ec.europa.eu). Deren Server sieht dabei die IP-Adresse und die Adresse der Datei (Ebene der Gebietseinteilung). Das Land wird erst im Browser ausgewählt. Sonst geht nichts dorthin: Daten aus Statable werden nicht gesendet, es gibt keine Cookies, und ohne den Klick geht keine Anfrage hinaus. Die Grenzen gehören EuroGeographics und dürfen nur nicht-kommerziell verwendet werden; auf der Karte und im Export steht der Vermerk der Quelle. Die Karten der Staaten der Welt und der Länder kommen vom eigenen Server; dafür geht keine Anfrage an die Kommission. Die Offline-Fassung bietet das Laden nicht an.", "Clicking \"Load boundaries from Eurostat\" (page \"Map\") sends a request to the European Commission (gisco-services.ec.europa.eu). Its server sees the IP address and the address of the file (level of the division into areas). The country is selected only in the browser. Nothing else goes there: no data from Statable is sent, there are no cookies, and without the click no request is sent. The boundaries belong to EuroGeographics and may only be used non-commercially; the map and the export carry the notice of the source. The maps of the countries of the world and of single countries come from the own server; no request goes to the Commission for them. The offline version does not offer loading.")}</p>
      <h2>{L("Wenn Daten von Eurostat geladen werden", "When data is loaded from Eurostat")}</h2>
      <p>{L("Beim Klick auf „Von Eurostat laden“ (Startseite, „Eurostat-Daten öffnen“) geht eine Anfrage an die Europäische Kommission (ec.europa.eu). Deren Server sieht dabei die IP-Adresse und die Abfrage (Datensatz und Filter). Sonst geht nichts dorthin: Daten aus Statable werden nicht gesendet, es gibt keine Cookies, und ohne den Klick geht keine Anfrage hinaus. Wofür die Kommission die Angaben nutzt, steht hier nicht; das regeln deren eigene Hinweise.", "Clicking \"Load from Eurostat\" (start page, \"Open Eurostat data\") sends a request to the European Commission (ec.europa.eu). Its server sees the IP address and the query (dataset and filters). Nothing else goes there: no data from Statable is sent, there are no cookies, and without the click no request is sent. What the Commission uses the details for is not stated here; its own notices regulate that.")}</p>
      {/if}
      <h2>{L("Beim Aufruf der Seite", "When you open the page")}</h2>
      <p>{@html L("Die Seite liegt auf einem Server der Hetzner Online GmbH in Deutschland (EU). Beim Laden übermittelt der Browser technisch nötige Angaben, zum Beispiel die IP-Adresse. Der Server nutzt sie nur, um die Dateien auszuliefern, und schreibt keine Zugriffsprotokolle. Rechtsgrundlage: Art. 6 Abs. 1 lit. f DSGVO (sichere Bereitstellung der Seite).", "The page is hosted on a server of Hetzner Online GmbH in Germany (EU). When loading, your browser sends technically necessary data such as the IP address. The server uses it only to deliver the files and keeps no access logs. Legal basis: Art. 6(1)(f) GDPR (secure provision of the page).")}</p>
      {#if MELDEN_SERVER}
      <h2>{L("Wenn eine Meldung gesendet wird", "When a report is sent")}</h2>
      <p>{@html L("Der Knopf „Melden“ sendet nur, wenn die Person auf „Senden“ klickt. Dann gehen der Text, die technischen Angaben (Stand der App, Sprache, Seite, Fenstergröße, Browser), auf Wunsch ein Bild vom Fenster und eine freiwillig eingetragene Antwortadresse an den Server von Statable. Dort werden sie gespeichert und als Mail an service@statable.eu weitergegeben; sie werden nur gebraucht, um die Meldung zu bearbeiten und, wenn eine Adresse angegeben ist, zu antworten. Das Bild kann Daten der Auswertung zeigen; es ist vor dem Senden zu sehen und lässt sich abwählen. Die Daten der Auswertung selbst gehen nicht mit. Der Server speichert dazu keine IP-Adressen; er zählt Meldungen je Adresse nur im Arbeitsspeicher, um Missbrauch zu bremsen. Rechtsgrundlage: Art. 6 Abs. 1 lit. a DSGVO (Einwilligung durch das Absenden), bei der Antwortadresse ebenso. Auf Wunsch wird eine Meldung gelöscht (Mail an service@statable.eu).", "The \"Report\" button sends only if the person clicks \"Send\". Then the text, the technical details (version of the app, language, page, window size, browser), on request a picture of the window and a voluntarily entered reply address go to the Statable server. There they are stored and passed on as an email to service@statable.eu; they are needed only to handle the report and, if an address is given, to reply. The picture can show data of the analysis; it can be seen before sending and can be switched off. The data of the analysis itself do not go along. The server stores no IP addresses for this; it counts reports per address only in working memory to slow down abuse. Legal basis: Art. 6(1)(a) GDPR (consent by sending), likewise for the reply address. On request a report is deleted (email to service@statable.eu).")}</p>
      <h2>{L("Wenn ein Lernpfad geteilt wird", "When a learning path is shared")}</h2>
      <p>{L("Beim Teilen eines eigenen Lernpfads legt Statable den Namen des Pfads und die Liste seiner Einheiten auf dem eigenen Server ab, damit ein kurzer Link entsteht (statable.eu/l/…). Angaben zu Personen, Lernstand, Daten der Auswertung und IP-Adresse gehen dabei nicht mit. Der Eintrag bleibt bestehen, damit der Link weiter funktioniert. Rechtsgrundlage: Art. 6 Abs. 1 lit. f DSGVO (Teilen von Lernpfaden). Die eigenen Pfade selbst bleiben im Browser.", "When you share one of your own learning paths, Statable stores the name of the path and the list of its units on its own server so that a short link can be created (statable.eu/l/…). No personal details, learning progress, analysis data or IP address are sent. The entry is kept so that the link keeps working. Legal basis: Art. 6(1)(f) GDPR (sharing learning paths). Your own paths themselves stay in the browser.")}</p>
      <h2>{L("Besucherzählung", "Visitor counting")}</h2>
      <p>{@html L("Statable zählt auf dem eigenen Server, wie oft die Seite gestartet wird und wie lange sie aktiv benutzt wird. Dazu kommen die eingestellte Sprache, die Art des Geräts (Handy, Tablet, Rechner), der Name der Website, von der jemand kam, welche Verfahren gerechnet und welche Programmteile geladen werden (R, R-Pakete, Offline-Fassung). Daten der Auswertung, Spaltennamen und Dateinamen gehen nie mit.", "Statable counts on its own server how often the page is started and how long it is actively used. It also counts the language setting, the type of device (phone, tablet, computer), the name of the website someone came from, which methods are calculated and which program parts are loaded (R, R packages, offline version). Analysis data, column names and file names are never sent.")}</p>
      <p>{@html L("Welche Auswertungen gerechnet, welche Lerneinheiten und Lernpfade geöffnet oder abgeschlossen und welche Hilfeartikel gelesen werden, zählt Statable nur als Summe je Tag, zum Beispiel „Faktorenanalyse: 564 Mal“. Gespeichert wird allein der Name des Verfahrens, der Einheit oder des Artikels, ohne Uhrzeit, ohne Zufallsnummer und ohne Verbindung zu einem Gerät oder einer Person. Es lässt sich daher nicht nachvollziehen, wer was gerechnet oder gelesen hat. Die Daten der Auswertung selbst gehen nie mit.", "Statable counts which analyses are run, which learning units and learning paths are opened or completed and which help articles are read only as a total per day, for example \"factor analysis: 564 times\". Only the name of the method, unit or article is stored - without time of day, without the random number and without any link to a device or a person. It is therefore not possible to tell who ran or read what. The analysis data itself is never sent.")}</p>
      <p>{@html L("Damit wiederkehrende Besuche erkennbar sind, legt Statable im lokalen Speicher des Browsers eine Zufallsnummer ab (kein Cookie). Sie hängt an keinem Namen und keiner IP-Adresse. Um die Besucher eines Tages zu zählen, bildet der Server außerdem aus IP-Adresse, Browserangabe und einem monatlich neuen Geheimwert eine Prüfsumme. Die IP-Adresse selbst wird nicht gespeichert, der Geheimwert nach spätestens zwei Monaten gelöscht. Die Zählwerte werden nach 25 Monaten gelöscht. Nichts geht an fremde Dienste.", "To recognise returning visits, Statable stores a random number in the browser's local storage (not a cookie). It is not linked to any name or IP address. To count the visitors of a day, the server also forms a checksum from the IP address, the browser details and a secret value that changes every month. The IP address itself is not stored, and the secret value is deleted after two months at the latest. The counts are deleted after 25 months. Nothing goes to third-party services.")}</p>
      <p>{@html L("Rechtsgrundlage: Art. 6 Abs. 1 lit. f DSGVO (berechtigtes Interesse, das kostenlose Angebot zu verbessern). Widerspruch: Die Zählung lässt sich hier abschalten. Dann wird die Zufallsnummer gelöscht, und dieser Browser sendet nichts mehr. Browser mit „Do Not Track“ oder „Global Privacy Control“ werden nicht gezählt.", "Legal basis: Art. 6(1)(f) GDPR (legitimate interest in improving the free service). Objection: counting can be switched off here. The random number is then deleted, and this browser sends nothing more. Browsers with \"Do Not Track\" or \"Global Privacy Control\" are not counted.")}</p>
      <p class="zaehl-schalter" aria-live="polite">
        {#if nichtVerfolgen}{L("Dieser Browser sendet „nicht verfolgen“ - er wird nicht gezählt.", "This browser sends \"do not track\" - it is not counted.")}
        {:else if zaehlAus}{L("Die Zählung ist in diesem Browser abgeschaltet.", "Counting is switched off in this browser.")} <button type="button" class="k" onclick={zaehlSchalten}>{L("Wieder einschalten", "Switch on again")}</button>
        {:else}{L("Die Zählung ist in diesem Browser eingeschaltet.", "Counting is switched on in this browser.")} <button type="button" class="k" onclick={zaehlSchalten}>{L("Abschalten", "Switch off")}</button>{/if}
      </p>
      {/if}
      {#if !OFFLINE}
      <h2>{L("Unterstützen (Spenden)", "Supporting Statable (donations)")}</h2>
      <p>{@html L("Auf der Seite <a href=\"#unterstuetzen\">Unterstützen</a> stehen Links zu Zahlungsseiten von Stripe. Sie öffnen in einem neuen Tab und werden erst beim Klick geladen; vorher geht nichts an Stripe. Bezahlt wird bei Stripe: Statable erfährt nicht, wer zahlt, und erhält keine Zahlungsdaten. Für die Zahlung gilt die Datenschutzerklärung von Stripe.", "The page <a href=\"#unterstuetzen\">Support</a> has links to payment pages of Stripe. They open in a new tab and are loaded only when clicked; nothing goes to Stripe before. Payment is made at Stripe: Statable does not learn who pays and receives no payment data. Stripe's privacy policy applies to the payment.")}</p>
      <p>{L("Nach jeweils 10 Stunden aktiver Nutzung zeigt Statable einen Hinweis auf diese Seite. Dafür zählt Statable die aktive Zeit im lokalen Speicher des Browsers (Tab sichtbar, in den letzten 5 Minuten eine Eingabe). Diese Zahl geht an keinen Server, ist von der Besucherzählung unabhängig und lässt sich auf der Seite Unterstützen abschalten. Sie verschwindet, wenn die Websitedaten gelöscht werden.", "After every 10 hours of active use, Statable shows a notice pointing to that page. For this, Statable counts the active time in the browser's local storage (tab visible, an input within the last 5 minutes). This number goes to no server, is independent of the visitor counting and can be switched off on the Support page. It disappears when the site data is deleted.")}</p>
      {/if}
      <h2>{L("Rechte", "Your rights")}</h2>
      {#if MELDEN_SERVER}
      <p>{@html L("Es gibt Rechte auf Auskunft, Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit und Widerspruch. Der Betreiber speichert keine Namen und keine IP-Adressen; die Zählwerte hängen nur an der Zufallsnummer im Browser. Wer sie nicht mehr will, schaltet die Zählung oben ab. Fragen bitte per Mail. Beschwerden: Österreichische Datenschutzbehörde, <a href=\"https://www.dsb.gv.at\" rel=\"noopener\">dsb.gv.at</a>.", "You have the right to access, correction, deletion, restriction, data portability and objection. The operator stores no names and no IP addresses; the counts are linked only to the random number in the browser. If you no longer want them, switch counting off above. Questions by email. Complaints: Austrian Data Protection Authority, <a href=\"https://www.dsb.gv.at\" rel=\"noopener\">dsb.gv.at</a>.")}</p>
      {:else}
      <p>{@html L("Es gibt Rechte auf Auskunft, Berichtigung, Löschung, Einschränkung, Datenübertragbarkeit und Widerspruch. Da der Betreiber keine Daten zu Personen speichert, ist meist nichts vorhanden. Fragen bitte per Mail. Beschwerden: Österreichische Datenschutzbehörde, <a href=\"https://www.dsb.gv.at\" rel=\"noopener\">dsb.gv.at</a>.", "You have the right to access, correction, deletion, restriction, data portability and objection. As the operator stores no personal data, there is usually nothing to report. Questions by email. Complaints: Austrian Data Protection Authority, <a href=\"https://www.dsb.gv.at\" rel=\"noopener\">dsb.gv.at</a>.")}</p>
      {/if}
      <h2>{L("Außerhalb der EU, auch in den USA", "Outside the EU, including the United States")}</h2>
      <p>{@html L("Für Nutzende in allen Ländern gilt dasselbe: Statable verkauft und teilt keine personenbezogenen Daten (auch nicht im Sinn des kalifornischen CCPA/CPRA), zeigt keine Werbung und verfolgt niemanden über andere Websites. Daten aus Studien bleiben auf dem eigenen Gerät - auch Daten von Studierenden oder Gesundheitsdaten werden nicht an Statable übertragen.", "The same applies to users in every country: Statable does not sell or share personal information (including within the meaning of California's CCPA/CPRA), shows no ads and does not track anyone across other websites. Study data stays on your own device - student records or health data are not transmitted to Statable either.")}</p>
      {#if MELDEN_SERVER}
      <p>{@html L("Signale wie „Do Not Track“ oder „Global Privacy Control“ schalten die Besucherzählung ab. Statable verfolgt niemanden über andere Websites.", "Signals such as \"Do Not Track\" or \"Global Privacy Control\" switch visitor counting off. Statable does not track anyone across other websites.")}</p>
      {:else}
      <p>{@html L("Signale wie „Do Not Track“ oder „Global Privacy Control“ ändern nichts, weil Statable ohnehin nichts verfolgt.", "Signals such as \"Do Not Track\" or \"Global Privacy Control\" change nothing, because Statable does not track anything in the first place.")}</p>
      {/if}
      <p>{@html L("Statable richtet sich an Erwachsene in Studium, Lehre, Forschung und Beruf, nicht an Kinder unter 13 Jahren, und erhebt auch von Kindern keine Daten.", "Statable is meant for adults in study, teaching, research and work, not for children under 13, and collects no data from children either.")}</p>
      <h2>{L("Änderungen", "Changes")}</h2>
      {#if MELDEN_SERVER}
      <p>{@html L("Änderungen dieser Erklärung stehen auf dieser Seite. Stand: 6. November 2026.", "Changes to this policy are posted on this page. Last updated: November 6, 2026.")}</p>
      {:else}
      <p>{@html L("Änderungen dieser Erklärung stehen auf dieser Seite. Stand: 18. Oktober 2026.", "Changes to this policy are posted on this page. Last updated: October 18, 2026.")}</p>
      {/if}
  {/if}
</section></div>

